+import { createHash } from "node:crypto";
+import { DynamoDBDocumentClient, GetCommand, PutCommand } from "@aws-sdk/lib-dynamodb";
+
+const TTL_S = 900;
+
+export function cacheKey(query: string, topK: number): string {
+  return createHash("sha256").update(`${topK}:${query.trim().toLowerCase()}`).digest("hex");
+}
+
+export async function getCached(ddb: DynamoDBDocumentClient, key: string) {
+  const r = await ddb.send(new GetCommand({ TableName: process.env.RETRIEVAL_CACHE!, Key: { pk: key } }));
+  return r.Item?.chunks as Chunk[] | undefined;
+}
+
+export async function putCached(ddb: DynamoDBDocumentClient, key: string, chunks: Chunk[]) {
+  await ddb.send(
+    new PutCommand({
+      TableName: process.env.RETRIEVAL_CACHE!,
+      Item: { pk: key, chunks, ttl: Math.floor(Date.now() / 1000) + TTL_S },
+    }),
+  );
+}
