 import { pool } from "../db";
+import { cacheKey, getCached, putCached } from "./cache";

 export async function searchChunks(tenantId: string, query: string, topK = 8): Promise<Chunk[]> {
+  const key = cacheKey(query, topK);
+  const hit = await getCached(ddb, key);
+  if (hit) return hit;
   const emb = await embed(query);
   const { rows } = await pool.query(
     `SELECT id, content FROM chunks
      WHERE tenant_id = $1
      ORDER BY embedding <=> $2 LIMIT $3`,
     [tenantId, emb, topK],
   );
+  await putCached(ddb, key, rows);
   return rows;
 }

