diff --git a/src/agent/summarizeDoc.ts b/src/agent/summarizeDoc.ts
--- a/src/agent/summarizeDoc.ts
+++ b/src/agent/summarizeDoc.ts
@@ -1,6 +1,27 @@
+import pLimit from "p-limit";
 import { summarizeChunk } from "./summarizeChunk";

+const MAX_CHUNKS = 20;
+const limit = pLimit(5);
+
 export async function summarizeDoc(tenantId: string, chunks: string[]) {
-  const out: string[] = [];
-  for (const c of chunks) out.push(await summarizeChunk(tenantId, c));
-  return { summary: out.join("\n") };
+  const picked = chunks.slice(0, MAX_CHUNKS);
+  const results = await Promise.all(
+    picked.map((c, i) =>
+      limit(async () => {
+        try {
+          return { i, ok: true as const, text: await summarizeChunk(tenantId, c) };
+        } catch (err) {
+          return { i, ok: false as const, error: String(err) };
+        }
+      }),
+    ),
+  );
+  const failed = results.filter((r) => !r.ok).map((r) => r.i);
+  return {
+    summary: results.flatMap((r) => (r.ok ? [r.text] : [])).join("\n"),
+    partial: failed.length > 0 || chunks.length > MAX_CHUNKS,
+    failedChunks: failed,
+    skippedChunks: Math.max(0, chunks.length - MAX_CHUNKS),
+  };
+}

