@@ -1,19 +1,43 @@
 import type { SQSEvent, SQSBatchResponse } from "aws-lambda";
 import { DynamoDBClient, PutItemCommand, DeleteItemCommand, UpdateItemCommand } from "@aws-sdk/client-dynamodb";
 import { runAgent } from "../agent/runAgent";

 const ddb = new DynamoDBClient({});
 const TableName = process.env.RUNS_TABLE!;

 export const handler = async (event: SQSEvent): Promise<SQSBatchResponse> => {
   const failures: { itemIdentifier: string }[] = [];
   for (const record of event.Records) {
     const msg = JSON.parse(record.body);
+    const key = { pk: { S: `run#${msg.runId}` } };
+    try {
+      await ddb.send(
+        new PutItemCommand({
+          TableName,
+          Item: { ...key, status: { S: "started" }, ttl: { N: String(Math.floor(Date.now() / 1000) + 86400) } },
+          ConditionExpression: "attribute_not_exists(pk)",
+        }),
+      );
+    } catch (e: any) {
+      if (e.name === "ConditionalCheckFailedException") continue;
+      failures.push({ itemIdentifier: record.messageId });
+      continue;
+    }
     try {
       await runAgent(msg);
+      await ddb.send(
+        new UpdateItemCommand({
+          TableName,
+          Key: key,
+          UpdateExpression: "SET #s = :d",
+          ExpressionAttributeNames: { "#s": "status" },
+          ExpressionAttributeValues: { ":d": { S: "done" } },
+        }),
+      );
     } catch (e) {
+      await ddb.send(new DeleteItemCommand({ TableName, Key: key }));
       failures.push({ itemIdentifier: record.messageId });
     }
   }
   return { batchItemFailures: failures };
 };
